import React from 'react';
import {
    View,
    Text,
    TouchableOpacity,
} from 'react-native';

import { useContexState } from '../../../hooks/context';
import { styles } from './styles';

export function HamburgerMenu() {
    const {
        hamburgerMenuActive,
        loginValue
    } = useContexState();

    const {
        setHamburgerMenuActive,
        setLoginMenuActive,
        setLoginValue
    } = useContexState();


    function Menu() {
        return <View style={{
            alignItems: 'flex-start',
            backgroundColor: 'rgba(0,0,0,0.8)',
            borderRadius: 7,
            borderWidth: 3,
            borderColor: '#356',
        }}>
            <TouchableOpacity
                onPress={() => {
                    setHamburgerMenuActive(false);
                    setLoginMenuActive(true);
                }}
                style={styles.containerButton} >
                <Text style={styles.textButton}>Entrar</Text>
            </TouchableOpacity>


            <TouchableOpacity
                onPress={() => { setHamburgerMenuActive(false) }}
                style={styles.containerButton} >
                <Text style={[styles.textButton]}>Meus números</Text>
            </TouchableOpacity>

            <TouchableOpacity
                onPress={() => { setHamburgerMenuActive(false) }}
                style={styles.containerButton} >
                <Text style={styles.textButton}>Quem Somos</Text>
            </TouchableOpacity>

            {loginValue.permission !== '' ? <TouchableOpacity
                onPress={() => setLoginValue({ name: '', password: '', permission: '' })}
                style={styles.containerButton} >
                <Text style={styles.textButton}>Sair</Text>
            </TouchableOpacity> : null}
        </ View>
    }

    return hamburgerMenuActive ?
        <>
            <TouchableOpacity onPress={() => {
                setHamburgerMenuActive(false);
            }} style={styles.containeMain} />

            <View style={styles.container} >
                <View />
                <Menu />
            </View>

        </> : null
};
